   [E("¿Qué sentido ayuda a imaginar «tic, tac, tic, tac»: la vista o el oído?", "El oído", "Es un sonido."),
    E("«Que no dejan de bailar»: ¿qué hacen las gotas en esta imagen?", "Caen y rebotan sin parar", "Se las imagina bailando continuamente."),
    E("¿El poema quiere decir que hay tambores de verdad sobre los techos?", "No", "Es una imagen para hacer imaginar el sonido de la lluvia.")],
   [E("Un lector dice: «El poema habla de música». Otro: «El poema habla de lluvia». ¿Quién interpreta mejor?", "El segundo", "El poema habla de lluvia que suena como música."),
    E("Si el poema dijera «cae una lluvia», sin tic ni tac, ¿se oiría tanto la lluvia?", "No", "Sin los sonidos repetidos se perdería el ritmo de las gotas.")],
